// main/passport_notify.h
// The device's sounds: short chimes that say "you are needed" or "that finished" without any
// network round trip and without a speech provider.
//
// Two properties are deliberate:
//   * The tone itself is generated by passport_tone, which is pure and host-tested; this module
//     only sequences notes and hands samples to the audio path.
//   * Playback goes through the audio arbiter, which closes the microphone for the duration.
//     This board cannot do acoustic echo cancellation, so a notification that recorded itself
//     would be a bug, not a nuisance. The invariant is enforced by the arbiter and asserted in
//     the work and voice tests.
#pragma once

#include <stdbool.h>
#include <stddef.h>

#include "esp_err.h"
#include "passport_work.h"

// Allocate the sample buffer once. Safe to call more than once.
esp_err_t passport_notify_init(void);

// Play the sound for an announcement. Blocking for the length of the chime, which is a few
// hundred milliseconds: call it from a worker, never from the interface.
//
// PASSPORT_WORK_ANNOUNCE_NONE does nothing. PASSPORT_WORK_ANNOUNCE_SPEAK is not implemented as
// speech; it is reported in the log and a chime is played instead, so a device configured for
// speech is still audible rather than silent about it.
esp_err_t passport_notify_play(passport_work_announcement_t announcement);

// What the last call did, for the console.
void passport_notify_report(char *out, size_t out_size);
